`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (sign-off). Reference: golden/reference (rp1__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg [31:0] data_in;
