  wire [0:0] wr_o; wire [0:0] ref_wr_o;
  rp1 dut (.data_in(data_in), .dest(dest), .source(source), .rd_clk(rd_clk), .wr_clk(wr_clk), .wr_en(wr_en), .reset(reset), .niout(niout), .rd_en(rd_en), .wr_o(wr_o));
  rp1__ref ref_i (.data_in(data_in), .dest(dest), .source(source), .rd_clk(rd_clk), .wr_clk(wr_clk), .wr_en(wr_en), .reset(reset), .niout(ref_niout), .rd_en(ref_rd_en), .wr_o(ref_wr_o));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1)
      if (ref_niout[tb_b] !== 1'bx && ref_niout[tb_b] !== 1'bz && niout[tb_b] !== ref_niout[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 32;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: niout = %h, expected %h", $time, tb_cyc, niout, ref_niout);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_rd_en[tb_b] !== 1'bx && ref_rd_en[tb_b] !== 1'bz && rd_en[tb_b] !== ref_rd_en[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: rd_en = %h, expected %h", $time, tb_cyc, rd_en, ref_rd_en);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_wr_o[tb_b] !== 1'bx && ref_wr_o[tb_b] !== 1'bz && wr_o[tb_b] !== ref_wr_o[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: wr_o = %h, expected %h", $time, tb_cyc, wr_o, ref_wr_o);
      end
  end endtask
  task tb_props; begin
  end endtask
  reg [31:0] tbc_p_niout, tbc_t_niout;
  reg [0:0] tbc_p_rd_en, tbc_t_rd_en;
  reg [0:0] tbc_p_wr_o, tbc_t_wr_o;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_niout = tbc_t_niout | ((ref_niout ^ tbc_p_niout) & ~(ref_niout ^ ref_niout)); tbc_p_niout = ref_niout;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_rd_en = tbc_t_rd_en | ((ref_rd_en ^ tbc_p_rd_en) & ~(ref_rd_en ^ ref_rd_en)); tbc_p_rd_en = ref_rd_en;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_wr_o = tbc_t_wr_o | ((ref_wr_o ^ tbc_p_wr_o) & ~(ref_wr_o ^ ref_wr_o)); tbc_p_wr_o = ref_wr_o;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_niout) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1) if (tbc_t_niout[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_rd_en) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_rd_en[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_wr_o) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_wr_o[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 3 checked outputs toggled, %0d of 34 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 29; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    data_in = 0; dest = 0; source = 0; wr_en = 0; reset = 0; reset = 1;
    tbc_t_niout = 0; tbc_p_niout = 0; tbc_t_rd_en = 0; tbc_p_rd_en = 0; tbc_t_wr_o = 0; tbc_p_wr_o = 0;
    for (tb_cyc = 0; tb_cyc < 5000; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk); #1;
      data_in = tb_flit(0);
      dest = {tb_rand(0)};
      source = {tb_rand(0)};
      wr_en = {tb_rand(0)};
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 40 == 0);
      tb_started = (tb_cyc >= 6);
      #3 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
